import app from 'flarum/forum/app';
import { getServiceWorkerRegistration } from './registerServiceWorker';
import addPushNotifications from './push/addPushNotifications';
import showOptInAlert from './push/showOptInAlert';
import { pushConfigured, supportsWebPush } from './push/utils';
import { syncPushSubscription } from './push/subscription';
import { usingAppleWebview } from './native/appleWebView';
app.initializers.add('fof-pwa', () => {
  addPushNotifications();
  app.beforeMount(async () => {
    if ('share' in navigator) {
      const {
        default: addShareControls
      } = await import(/* webpackChunkName: 'forum/share/addShareControls', webpackMode: 'lazy-once' */ './share/addShareControls');
      addShareControls();
    }
    if (usingAppleWebview()) {
      const {
        default: addFirebasePushNotifications
      } = await import(/* webpackChunkName: 'forum/native/addFirebasePushNotifications', webpackMode: 'lazy-once' */ './native/addFirebasePushNotifications');
      addFirebasePushNotifications();
    }
    showOptInAlert();
    void getServiceWorkerRegistration().then(registration => {
      if (!registration || !supportsWebPush() || !pushConfigured() || Notification.permission !== 'granted') {
        return;
      }
      return syncPushSubscription(registration);
    }).catch(error => {
      console.error('[fof-pwa] SW initialization failed:', error);
    });
  });
});flarum.reg.addChunkModule('689', '559', 'fof-pwa', 'forum/share/addShareControls');
flarum.reg.addChunkModule('689', '559', 'fof-pwa', 'forum/helpers/url');
flarum.reg.addChunkModule('165', '455', 'fof-pwa', 'forum/native/addFirebasePushNotifications');