import app from 'flarum/forum/app';
import { getVapidPublicKey } from './utils';
export async function syncPushSubscription(registration) {
  const existingSubscription = await registration.pushManager.getSubscription();
  const subscription = existingSubscription ?? (await registration.pushManager.subscribe({
    userVisibleOnly: true,
    applicationServerKey: getVapidPublicKey()
  }));
  await app.request({
    method: 'POST',
    url: `${app.forum.attribute('apiUrl')}/push_subscriptions`,
    body: {
      data: {
        attributes: subscription.toJSON()
      }
    }
  });
}